for s in specs:
 scope=box(*s['scope']);fs=[f for f in ways if f['properties']['name'] in s['roads'] and scope.covers(shape(f['geometry']))]
 if not fs:raise ValueError(s['name'])
 poly=unary_union([shape(f['geometry']) for f in fs]).convex_hull.intersection(city)
 if s['code']=='L2':
  # Municipal scheme treats these named units separately; retain the residential crescent.
  poly=poly.difference(polys['Gi2']).difference(polys['L3'])
  prior=json.load(open(P.parent/'features.geojson'))['features']
  poly=poly.difference(unary_union([shape(f['geometry']) for f in prior if f['properties']['municipality']=='Keszthely' and f['properties']['name'] in ['Történelmi belváros','Szalasztó']]))
